// Types of the tenbri package (tenbri.js). The native addon's own types are generated by napi-rs
// into index.d.ts.

/** An entry as stored (format v1, spec/format-v1.md). */
export interface Entry {
  v: number
  id: string
  stream: string
  seq: number
  ts: string
  kind: 'decision' | 'approval' | 'key' | 'reconcile' | 'note'
  phase?: 'intent' | 'outcome'
  intent?: string
  status?: Status
  source?: 'sdk' | 'proxy' | 'ingest'
  durability?: 'local' | 'replicated' | 'postgres'
  principal?: { kind: PrincipalKind; id: string }
  action?: { type: string; target?: string }
  subject?: string
  inputs?: Input[]
  rule?: { ref: string; version: string; result: string }
  prev?: string
  signer: string
  sig: string
  [member: string]: unknown
}

/** A draft entry: what the writer does not fill in (`v`, `stream`, `seq`, `prev`, `signer`, `sig`).
 * Give it an `id` (`newId()`) to make retries idempotent. */
export type Draft = Omit<Partial<Entry>, 'principal'> & { principal?: Principal }

export type Status = 'ok' | 'error' | 'refused' | 'unknown'
export type PrincipalKind = 'agent' | 'person' | 'service'
/** `{ kind, id }`, `'agent:support'`, or `'support'` (an agent). */
export type Principal = string | { kind: PrincipalKind; id: string }
export interface Input {
  ref: string
  version: string
  digest: string
}

export interface OpenOptions {
  /** The keys directory; default `$TENBRI_KEYS`, else `~/.config/tenbri/keys`. Never inside the
   * stream. Without the stream's keys there, the stream opens read-only. */
  keys?: string
  /** The genesis key to pin: `sha256:…` fingerprint or `ed25519:…` public key. */
  key?: string
  /** Create the stream and its keys if there is none. */
  create?: boolean
  /** Keys the digests of inputs a run reads (HMAC-SHA256). */
  digestKey?: string | Uint8Array
}

export interface DecisionOptions extends Omit<Draft, 'action'> {
  action: string
  target?: string
}

export interface VerifyReport {
  /** Verified: nothing broken, against a pinned key. */
  ok: boolean
  stream: string | null
  /** Entries checked before the first break, or all of them. */
  entries: number
  /** The fingerprint checked against; null when unpinned, which proves nothing about the writer. */
  pinnedKey: string | null
  broken: { seq: number; code: string; message: string } | null
  /** The size of the latest checkpoint, which the stream matched, if it has one. */
  checkpoint: number | null
}

export interface QueryFilter {
  action?: string
  target?: string
  principal?: Principal
  subject?: string
  /** `'ref@version'` strings or `[ref, version]` pairs; all must be among the entry's inputs. */
  inputs?: Array<string | [string, string]>
  afterSeq?: number
  limit?: number
}

export interface Match {
  /** `verified`, `unpinned` (no key pinned at open) or `broken`. */
  verification: 'verified' | 'unpinned' | 'broken'
  entry: Entry
}

export declare class Tenbri {
  /** Opens the stream at `url`: a directory, `file://…`, `s3://bucket/prefix` or `r2://bucket/prefix`
   * (credentials from `AWS_*`; `CLOUDFLARE_ACCOUNT_ID` for R2). */
  static open(url: string | URL, options?: OpenOptions): Promise<Tenbri>
  /** The stream id, `tnb1:…`. */
  readonly id: string
  /** The genesis key's fingerprint: what a verifier pins. */
  readonly fingerprint: string | null
  /** Whether this machine holds the keys to write the stream. */
  readonly writable: boolean
  /** The keyed digest of an input, `hmac-sha256:<hex>`: with the `digestKey` given at open, else
   * `subject`'s data key (the tenant's without one) from the local key store. */
  digest(content: string | Uint8Array, options?: { subject?: string }): string
  append(entry: Draft): Promise<Entry>
  /** Records an intent, durable before the action runs. */
  intent(draft: Draft): Promise<Entry>
  /** Records the outcome of `intent` (the entry, or its id). */
  outcome(intent: Entry | string, status?: Status, fields?: Draft): Promise<Entry>
  /** Records a decision around `fn`: intent before, outcome after (`ok`, `refused`, `error`). */
  decision<T>(options: DecisionOptions, fn: (intent: Entry) => T | Promise<T>): Promise<T>
  run<T>(options: { principal: Principal }, fn: (run: Run) => T | Promise<T>): Promise<T>
  verify(key?: string): Promise<VerifyReport>
  query(filter?: QueryFilter): Promise<Match[]>
  flush(): Promise<void>
  close(): Promise<void>
  /** `await using log = ...`: closed at the end of the scope. */
  [Symbol.asyncDispose](): Promise<void>
}

export interface InitOptions {
  /** The stream: a directory or `s3://bucket/prefix`. Default `$TENBRI_STREAM`. */
  stream?: string | URL
  /** The keys directory, apart from the stream. Default `$TENBRI_KEYS`, else `~/.config/tenbri/keys`. */
  keys?: string
  /** Who acts when nothing narrower says. Default `$TENBRI_AGENT`. */
  agent?: Principal
  /** Who answers the frameworks' approval prompts. Default `$TENBRI_APPROVER`. */
  approver?: Principal
  /** The action schemas. Default `$TENBRI_SCHEMA`, else `./tenbri.toml` when there is one. */
  schema?: string
  /** The genesis key to pin. */
  key?: string
  /** Keys input digests; default the local key store's data keys. */
  digestKey?: string | Uint8Array
  /** Let actions run, unrecorded and with a warning, when their intent cannot be written. */
  failOpen?: boolean
}

/** What a schema or the code says about a tool, per tool name. */
export interface ActionSpec {
  /** The action type; default the tool's name. */
  action?: string
  /** A template of the tool's arguments (`'stripe:{charge}'`) or a function of them. */
  target?: string | ((args: Record<string, any>) => string)
  subject?: string | ((args: Record<string, any>) => string)
  /** `'policy:refund@14'`: the rule that allowed it. */
  policy?: string
}
export type Actions = Record<string, ActionSpec>

/** The intent fields of a tool call. */
export interface Described {
  action?: string
  target?: string
  subject?: string
  rule?: { ref: string; version: string; result: string }
}

/** The stream `init()` opened, with the settings the rest of the process uses. */
export declare class Default extends Tenbri {
  readonly agent?: Principal
  readonly approver?: Principal
  /** The action schemas of tenbri.toml, by action type. */
  readonly actions: Record<string, { target?: string; policy?: string; [k: string]: unknown }>
  readonly failOpen: boolean
}

/** Opens the process's default stream (made with its keys on first use), closed when the process
 * is about to exit. Options default to their `TENBRI_*` variables. Awaiting it is optional: a
 * decision waits for it, and throws what it threw. */
export declare function init(options?: InitOptions): Promise<Default>
/** The default stream, once `init()` has opened it. */
export declare function defaultStream(): Promise<Default>
/** Runs `fn` as `principal`: decisions in it, and in what it starts, are theirs. */
export declare function agent<T>(principal: Principal, fn: () => T): T
/** The principal of the innermost `agent()` scope, if any. */
export declare function scopedAgent(): { kind: PrincipalKind; id: string } | undefined
/** Who acts: `explicit`, else the innermost `agent()`, else `init({ agent })`. */
export declare function who(explicit?: Principal): { kind: PrincipalKind; id: string }
/** Who approved: `configured` (or what it returns for `args`), else `init({ approver })`. */
export declare function approverOf<A extends unknown[]>(
  configured: Principal | ((...args: A) => Principal | undefined) | undefined,
  ...args: A
): Principal | undefined
/** The intent fields of a tool call, from `actions` over the action schemas of tenbri.toml. */
export declare function describe(tool: string, args: Record<string, any>, actions?: Actions): Described

export type PinSpec = { ref: string; version: string } & ({ content: string | Uint8Array } | { digest: string })

export interface RecordOptions<A extends unknown[]> extends Omit<Draft, 'action' | 'inputs' | 'subject'> {
  action: string
  /** A template of the arguments (`'stripe:{charge}'` reads the first argument's `charge`, `'{1}'`
   * the second argument) or a function of them. */
  target?: string | ((...args: A) => string)
  subject?: string | ((...args: A) => string)
  /** `'policy:refund@14'`: the rule that allowed the action. */
  policy?: string
  inputs?: PinSpec[] | ((...args: A) => PinSpec[])
  /** Default `init({ failOpen })`. */
  failOpen?: boolean
}

/** `fn`, each call recorded as a decision on the default stream: the intent durable before it
 * runs, then `ok`, `refused` (it threw `Refused`), `error` or `unknown` (an AbortError). */
export declare function decision<A extends unknown[], R>(
  options: RecordOptions<A>,
  fn: (...args: A) => R | Promise<R>,
): (...args: A) => Promise<R>

export declare class Run {
  readonly principal: { kind: PrincipalKind; id: string }
  /** Records a read: the next decision lists it among its inputs, with its keyed digest. */
  read(ref: string, read: { version: string; content?: string | Uint8Array; digest?: string }): void
  decision<T>(options: DecisionOptions, fn: (intent: Entry) => T | Promise<T>): Promise<T>
}

/** Throw inside a decision when your own policy refuses the action: recorded as `refused`. */
export declare class Refused extends Error {}

/** A Tenbri failure, with its stable TENBRI_* code, shared with tenbrid. */
export declare class TenbriError extends Error {
  readonly code: string
  /** The format v1 error code (`bad_signature`, …), where there is one. */
  readonly reason?: string
  /** The id of the entry being written: retry with it. */
  readonly id?: string
}
export declare class InvalidRequestError extends TenbriError {}
export declare class InvalidEntryError extends TenbriError {}
export declare class NotFoundError extends TenbriError {}
export declare class IdempotencyConflictError extends TenbriError {}
export declare class WriteConflictError extends TenbriError {}
export declare class DeadlineExceededError extends TenbriError {}
export declare class StoreUnavailableError extends TenbriError {}
export declare class NoSessionKeyError extends TenbriError {}
export declare class StreamBrokenError extends TenbriError {}

/** A new entry id (ULID), for idempotent retries. */
export declare function newId(): string
export declare const version: string
